/**
 * Walk a slot's module files, import one, and check that its default export carries an expected definition brand.
 */
import { join } from "node:path";
import { getDefinitionKind } from "../brand.js";
import { displayPath, pushModuleLoadDiagnostic } from "./context.js";
import { isDirectory, isModuleFile, moduleStem, sortedEntries } from "./fs.js";
import { validateName } from "./names.js";
/** The module files of a slot directory whose filenames are valid names. */
export async function moduleEntries(ctx, dir, kind) {
    if (!(await isDirectory(dir))) {
        return [];
    }
    const entries = [];
    for (const entry of await sortedEntries(dir)) {
        const path = join(dir, entry.name);
        if (entry.isDirectory()) {
            ctx.diagnostics.push({
                severity: "warning",
                path: displayPath(ctx, path),
                message: `Nested ${kind} directories are not supported; ignoring.`,
            });
            continue;
        }
        if (!entry.isFile() || !isModuleFile(entry.name)) {
            continue;
        }
        const name = moduleStem(entry.name);
        if (validateName(ctx, kind, name, path)) {
            entries.push({ name, path });
        }
    }
    return entries;
}
/**
 * The module's default export when it carries one of the expected brands;
 * a diagnostic and `undefined` otherwise.
 */
export async function importDefault(ctx, modulePath, expected) {
    let mod;
    try {
        mod = await ctx.importModule(modulePath);
    }
    catch (error) {
        pushModuleLoadDiagnostic(ctx, modulePath, error);
        return undefined;
    }
    const kinds = typeof expected === "string" ? [expected] : expected;
    const kind = getDefinitionKind(mod.default);
    if (kind !== undefined && isImportableKind(kind, kinds)) {
        return mod.default;
    }
    const helpers = kinds.map(helperCall).join(" or ");
    const expectedKinds = kinds.join(" or ");
    const article = /^[aeiou]/.test(expectedKinds) ? "an" : "a";
    const message = kind === undefined
        ? `Module must default-export ${helpers}.`
        : `Expected ${article} ${expectedKinds} definition but found "${kind}" (wrong authored slot?).`;
    ctx.diagnostics.push({
        severity: "error",
        code: "invalid_definition",
        path: displayPath(ctx, modulePath),
        message,
    });
    return undefined;
}
function isImportableKind(kind, allowed) {
    return allowed.some((item) => item === kind);
}
/** How a definition of `kind` is authored: `defineTool({ ... })`, `disableTool()`. */
export function helperCall(kind) {
    const name = DEFINE_HELPER_NAME[kind];
    return kind === "disabled" || kind.startsWith("disabled-") ? `${name}()` : `${name}({ ... })`;
}
const DEFINE_HELPER_NAME = {
    agent: "defineAgent",
    tool: "defineTool",
    skill: "defineSkill",
    extension: "defineExtension",
    "disabled-tool": "disableTool",
    "disabled-connection": "disableConnection",
    disabled: "disable",
    connection: "defineConnection",
    channel: "defineChannel",
    "http-channel": "httpChannel",
    schedule: "defineSchedule",
    reminder: "defineReminder",
    hook: "defineHook",
    storage: "defineStorage",
    artifacts: "defineArtifacts",
};
